use evm_verify::api::{EVMVerify, AnalysisConfig, VulnerabilityType, Vulnerability};
use evm_verify::api::types::VerificationStrategy;
use std::time::Instant;
use hex;
use std::collections::HashMap;

fn main() -> Result<(), Box<dyn std::error::Error>> {
    // The bytecode to analyze (Joe Router)
    let bytecode_hex = "";

    // Decode hex bytecode
    println!("Decoding bytecode...");
    let bytecode_bytes = hex::decode(bytecode_hex.trim_start_matches("0x"))?;
    let bytecode = ethers::types::Bytes::from(bytecode_bytes);

    // Configure analysis
    let config = AnalysisConfig {
        analyze_constructor: true,
        analyze_runtime: true,
        max_depth: 100,
        detect_reentrancy: true,
        detect_cross_contract_reentrancy: true,
        detect_arithmetic: true,
        detect_access_control: true,
        detect_delegate_call: true,
        detect_flash_loan: true,
        detect_oracle_manipulation: true,
        detect_governance: true,
        detect_gas_griefing: true,
        detect_precision_loss: true,
        detect_event_emission: true,
        detect_front_running: true,
        test_mode: false,
        verification_strategy: VerificationStrategy::Groth16,
    };

    // Create a verifier instance
    let verifier = EVMVerify::with_config(config);

    // Analyze bytecode
    println!("Analyzing bytecode for vulnerabilities...");
    let start = Instant::now();
    let report = verifier.analyze_bytecode(bytecode)?;
    let elapsed = start.elapsed();
    println!("Analysis completed in {:.2?}", elapsed);

    // Print results
    println!("Contract size: {} bytes", report.contract_size);
    println!("Delegate calls: {}", report.delegate_calls);
    println!("Memory accesses: {}", report.memory_accesses);
    println!("Storage accesses: {}", report.storage_accesses);

    // Group vulnerabilities by type
    if !report.vulnerabilities.is_empty() {
        println!("\nFound {} vulnerabilities:", report.vulnerabilities.len());
        
        // Group vulnerabilities by type using a string representation as the key
        let mut by_type: HashMap<String, Vec<&Vulnerability>> = HashMap::new();
        for vuln in &report.vulnerabilities {
            // Convert vulnerability type to string for hashing
            let type_string = format!("{:?}", vuln.vulnerability_type);
            by_type.entry(type_string)
                   .or_insert_with(Vec::new)
                   .push(vuln);
        }
        
        // Print vulnerabilities by type
        for (type_str, vulns) in by_type {
            println!("\nType: {}", type_str);
            println!("Count: {}", vulns.len());
            
            // Sort by severity while maintaining references
            let mut sorted_vulns = vulns.clone();
            sorted_vulns.sort_by(|a, b| b.severity.cmp(&a.severity));
            
            // Print details
            for vuln in sorted_vulns {
                println!("\n   Title: {}", vuln.title);
                println!("   Severity: {:?}", vuln.severity);
                println!("   Description: {}", vuln.description);
                println!("   Recommendation: {}", vuln.recommendation);
                println!();
            }
        }
    } else {
        println!("No vulnerabilities detected!");
    }
    
    Ok(())
}
